#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
run_wizard() {

TOTAL_STAGES=9

REPO_ROOT="$(git -C "$(dirname "$0")" rev-parse --show-toplevel 2>/dev/null || pwd)"
SECRETS_FILE="$REPO_ROOT/secrets/secrets.yaml"
WROTE_SECRETS=()

# Run sops from PATH if present, otherwise straight off nixpkgs.
sops_do() {
  export SOPS_AGE_KEY_FILE="${SOPS_AGE_KEY_FILE:-$HOME/.config/sops/age/keys.txt}"
  if command -v sops >/dev/null 2>&1; then sops "$@"; else nix run nixpkgs#sops -- "$@"; fi
}

# slack_probe METHOD TOKEN -> "<ok|err>\t<detail>" on stdout.
slack_probe() {
  local method="$1" token="$2" out
  out=$(curl -sS -m 20 -X POST -H "Authorization: Bearer $token" \
        "https://slack.com/api/$method" 2>/dev/null) || { printf 'err\tnetwork\n'; return 0; }
  python3 - "$out" <<'PY'
import json, sys
try:
    d = json.loads(sys.argv[1])
except Exception:
    print("err\tbad-json"); raise SystemExit
if d.get("ok"):
    print("ok\t" + str(d.get("team") or d.get("user") or "valid")[:60])
else:
    print("err\t" + str(d.get("error") or "unknown"))
PY
}

write_secret() {
  local key="$1" value="$2"
  if [[ -z "$value" ]]; then warn "no value captured for $key; skipping"; return 0; fi
  if sops_do set "$SECRETS_FILE" "[\"$key\"]" "\"$value\"" >/dev/null 2>&1; then
    printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$SECRETS_FILE"
    WROTE_SECRETS+=("$key")
  else
    warn "couldn't write $key (missing age key?)"
    SKIPPED+=("$key  →  sops $SECRETS_FILE")
  fi
}

banner "Hermes → Slack control workspace"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Create a dedicated Slack workspace"
say "Hermes will live in its own Slack workspace, separate from work Slack."
step "Sign in with an email you control and enter the code Slack emails you."
step "Name the workspace something obvious, e.g. hermes-flakm."
step "Skip inviting teammates; you can add people later."
note "A private workspace keeps Hermes alerts out of the Coralogix Slack."
open_url "https://slack.com/create"
pause "Created the workspace? Press Enter."

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Create the Hermes app"
step "Click 'Create New App' → 'From scratch'."
step "App Name: Hermes."
step "Pick the workspace you just created."
step "Click 'Create App'."
open_url "https://api.slack.com/apps"
note "Keep this tab open; the next stages configure it."
pause "App created? Press Enter."

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Add bot token scopes"
say "In the app: OAuth & Permissions → Scopes → Bot Token Scopes → Add an OAuth Scope."
step "chat:write           — post and update the cards and replies"
step "im:history           — read your DM replies"
step "im:read, im:write    — open and read the DM channel"
step "app_mentions:read    — answer @Hermes mentions"
step "commands             — the /hermes slash command"
step "users:read, channels:read — show names on cards"
step "files:write          — forward thread attachments into your DM"
note "Scopes are case-sensitive; pick each from the dropdown."
pause "All scopes added? Press Enter."

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Install the app and capture the bot token"
say "This installs Hermes into the workspace and reveals the bot token."
step "Still on OAuth & Permissions, click 'Install to Workspace' → 'Allow'."
step "Copy the 'Bot User OAuth Token' (starts with xoxb-)."
while :; do
  ask_secret CONTROL_SLACK_BOT_TOKEN "Paste the bot token (xoxb-…):"
  if [[ "$CONTROL_SLACK_BOT_TOKEN" != xoxb-* ]]; then
    warn "That doesn't start with xoxb-."; continue
  fi
  probe="$(slack_probe auth.test "$CONTROL_SLACK_BOT_TOKEN")"
  if [[ "$probe" == ok$'\t'* ]]; then say "✓ Slack accepted it — team: ${probe#*$'\t'}"; break; fi
  warn "Slack said: ${probe#*$'\t'}"
  confirm "Try again?" || break
done

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Create the app-level token (Socket Mode)"
say "Socket Mode needs a separate app-level token with connections:write."
step "Basic Information → App-Level Tokens → 'Generate Token and Scopes'."
step "Name it 'socket', add scope 'connections:write', click Generate."
step "Copy the token (starts with xapp-)."
note "The 'Token Name' is just a label; the token itself starts xapp-."
while :; do
  ask_secret CONTROL_SLACK_APP_TOKEN "Paste the app-level token (xapp-…):"
  if [[ "$CONTROL_SLACK_APP_TOKEN" != xapp-* ]]; then
    warn "That doesn't start with xapp-."; continue
  fi
  probe="$(slack_probe apps.connections.open "$CONTROL_SLACK_APP_TOKEN")"
  if [[ "$probe" == ok$'\t'* ]]; then say "✓ app-level token works"; break; fi
  warn "Slack said: ${probe#*$'\t'}"
  confirm "Try again?" || break
done

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Turn on Socket Mode and subscribe to events"
step "Sidebar → Socket Mode → toggle 'Enable Socket Mode' ON."
step "Sidebar → Event Subscriptions → toggle ON."
step "Under 'Subscribe to bot events' → 'Add Bot User Event' → message.im."
step "Add another bot event → app_mention."
step "Click 'Save Changes'."
note "message.im lets Hermes read your DM replies; app_mention lets you @Hermes."
pause "Saved? Press Enter."

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Enable interactivity and the /hermes command"
step "Sidebar → Interactivity & Shortcuts → toggle ON (no URL needed in Socket Mode)."
step "Sidebar → Slash Commands → 'Create New Command'."
step "Command: /hermes"
step "Short Description: Ask Hermes about a thread"
step "Usage Hint: [list | history <query> | investigate | draft | snooze 2h]"
step "Click 'Save'."
pause "Saved? Press Enter."

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "Find your member id in the new workspace"
say "Hermes needs your member id in THIS workspace so it can DM you."
step "In Slack, open the Hermes app (Apps → Hermes) and send it any DM, e.g. 'hi'."
step "Click your avatar → Profile → ⋯ (More) → 'Copy member ID'."
note "It looks like U01AB2CD3EF — this is not your work-workspace id."
while :; do
  ask CONTROL_SLACK_USER_ID "Paste your member id (U…):"
  if [[ "$CONTROL_SLACK_USER_ID" =~ ^[UW][A-Z0-9]{6,}$ ]]; then say "✓ looks good"; break; fi
  warn "That doesn't look like a Slack member id."
  confirm "Try again?" || break
done

# ── Stage 9 ───────────────────────────────────────────────────────────────
stage "Store the three values in sops"
if [[ ! -f "$SECRETS_FILE" ]]; then
  warn "secrets file not found at $SECRETS_FILE"
  SKIPPED+=("secrets file missing")
else
  note "Writes encrypted values into secrets/secrets.yaml (key: \$HOME/.config/sops/age/keys.txt)."
  note "First run may fetch sops via 'nix run nixpkgs#sops'."
  if confirm "Write all three secrets now?"; then
    write_secret hermes_control_slack_bot_token "$CONTROL_SLACK_BOT_TOKEN"
    write_secret hermes_control_slack_app_token "$CONTROL_SLACK_APP_TOKEN"
    write_secret hermes_control_slack_user_id "$CONTROL_SLACK_USER_ID"
  else
    warn "Skipped; add them later with: sops $SECRETS_FILE"
    SKIPPED+=("hermes_control_slack_* secrets")
  fi
fi
if (( ${#WROTE_SECRETS[@]} )); then
  note "Wrote: ${WROTE_SECRETS[*]}"
fi
say "Next: push the module branch, 'nix flake update coralogix-private', then 'nixos-rebuild switch'."

finish
}

run_wizard "$@"; exit
